-- Cached secondary-source horse results for the final ten 2026 Prix Jacques le Marois runners.
-- Markup details remain in an ignored operator profile; rows retain source provenance.

begin;
on conflict (source, source_horse_id, source_race_id) where source_race_id is not null
do update set race_date=excluded.race_date, venue=excluded.venue, race_day_sequence=excluded.race_day_sequence, race_name=excluded.race_name, source_race_url=excluded.source_race_url, finish_position=excluded.finish_position, finish_position_text=excluded.finish_position_text, jockey_name=excluded.jockey_name, source_jockey_id=excluded.source_jockey_id, surface=excluded.surface, distance_metres=excluded.distance_metres, going=excluded.going, updated_at=now();
commit;
